const CONTRACT='BA_BIAS_MARKET_BIAS_V2';
export function legacyBias(input,{bias='BULLISH',reason='N1',strength='LOW'}={}){
 const price=input.currentFacts.find(e=>e.category==='PRICE'),oi=input.currentFacts.find(e=>e.category==='OPEN_INTEREST'),volume=input.currentFacts.find(e=>e.category==='VOLUME');
 const current=price.factRef,nonprice=(oi||volume).factRef;
 const interpretations=[{id:'participation',factRefs:[current,nonprice],knowledgeRefs:['K1-03','K2-02'],observation:`价格观察 {{${current}}} 与OI观察 {{${nonprice}}}，保留各自时间口径。`,interpretation:'这是交易结果与未平仓参与背景的共同观察，不能识别主动开平仓。',applicationConditions:['仅比较已验证数量与明确观察窗口，不能把不同采样误称同一时点。'],limitations:['未平仓变化不识别哪一方主动；本合成案例只验证公开证据合同。'],statementClass:'CONDITIONAL_RELATION'}];
 const evidence={interpretationId:'participation',factRefs:[current,nonprice],knowledgeRefs:['K1-03','K2-02'],relevance:'当前价格表现结合数量参与背景进行评估；数量不是独立方向信号。'};
 const conflicts=[];const assessments=[];
 if(['N2','N5'].includes(reason)&&bias==='NO_EDGE'){
  const second=input.currentFacts.find(e=>e.category==='PRICE'&&e.window==='4h')||price;
  interpretations.push({id:'competition',factRefs:[second.factRef],knowledgeRefs:['K1-01'],observation:`竞争观察 {{${second.factRef}}}`,interpretation:'不同观察窗口回答的问题存在歧义，不能按窗口数量投票。',applicationConditions:['时间与定义明确的不同回看观察。'],limitations:['仅有价格差异不足以确定哪个解释占优。'],statementClass:'MECHANISM'});
  conflicts.push({interpretationId:'competition',factRefs:[second.factRef],knowledgeRefs:['K1-01'],relevance:'跨观察窗口的重要竞争解释不能解决。'});assessments.push({interpretationId:'competition',disposition:'UNRESOLVED',reason:'现有事实不能区分两个观察窗口对当前偏向的意义。',factRefs:[second.factRef],knowledgeRefs:['K1-01']});
 }
 const previous=input.previousFacts?.find(e=>e.originalId===price.originalId);
 const a={contract:CONTRACT,contextId:input.contextId,symbol:input.symbol,bias,strength:bias==='NO_EDGE'?null:strength,marketInterpretation:interpretations,supportingEvidence:bias==='NO_EDGE'?[]:[evidence],conflictingEvidence:conflicts,knowledgeReferences:[...new Set(interpretations.flatMap(i=>i.knowledgeRefs))],decisionBasis:{synthesis:bias==='NO_EDGE'?'现有事实未能提供可辩护方向优势；价格符号或未证实行为不能决定方向。':'当前价格与非价格参与背景提供有条件偏向，保留主动行为不可确认的限制。',principalInterpretationIds:['participation'],relevantNonPriceFactRefs:bias==='NO_EDGE'?[]:[nonprice],nonPriceContribution:bias==='NO_EDGE'?null:`{{${nonprice}}} 提供未平仓参与背景，改变当前价格证据的可靠性解释，不作为独立方向票。`,conflictAssessments:assessments,noImportantConflictReason:conflicts.length?null:'所有当前有效观察均已覆盖；此合成案例未声明额外重要竞争解释。',unknownInformationImpact:'具体参与者开平仓不能确认，因此不给确定性因果或更强方向承诺。',changeFactRefs:previous?[current,previous.factRef]:[],changeImpact:previous?'前次与当前事实观察变化需要重新审视参与关系，先前Bias不作预设答案。':null},noEdgeReasons:bias==='NO_EDGE'?[reason]:[],uncertainties:[{kind:'UNPROVEN_PARTICIPANT_BEHAVIOR',description:'无法确认主动开仓、平仓或强平行为。',relatedFactRefs:[nonprice],knowledgeRefs:['K1-03'],effectOnBias:'不能将未证实行为作为方向确认。'}],reassessmentTriggers:[{kind:'UPDATED_OI_OBSERVATION',baselineFactRefs:[nonprice],knowledgeRefs:['K1-03'],description:'获得新的数量观察后复核其与价格证据的关系。',existingConditionFactRef:null,effect:'REASSESS_ONLY'}],factCoverage:input.currentFacts.map(e=>({factRef:e.factRef,treatment:conflicts.some(c=>c.factRefs.includes(e.factRef))?'CONFLICT':bias!=='NO_EDGE'&&[current,nonprice].includes(e.factRef)?'SUPPORT':'CONTEXT',interpretationIds:conflicts.some(c=>c.factRefs.includes(e.factRef))?['competition']:[current,nonprice].includes(e.factRef)?['participation']:[],reason:'保留该观测口径，不按正负号投票；核心与竞争作用见公开解释。'}))};return a;
}
